import{_ as s,o as e,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"大田","description":"","frontmatter":{"title":"大田","date":"2026-11-08T00:00:00.000Z","seq":52,"categories":["美文","诗经"],"collection":"《诗经 · 小雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·小雅/大田.md","filePath":"blogs/诗经·小雅/大田.md"}'),p={name:"blogs/诗经·小雅/大田.md"};function c(l,a,n,r,_,m){return e(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="大田" tabindex="-1">大田 <a class="header-anchor" href="#大田" aria-label="Permalink to &quot;大田&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　甫田之什</p><div class="poem"><p class="poem-stanza">大田多稼，既种既戒，既备乃事。以我覃耜，俶载南亩。</p><p class="poem-stanza">播厥百谷，既庭且硕，曾孙是若。</p><p class="poem-stanza">既方既皂，既坚既好，不稂不莠。去其螟螣，及其蟊贼，</p><p class="poem-stanza">无害我田稚。田祖有神，秉畀炎火。</p><p class="poem-stanza">有渰萋萋，兴雨祈祈。雨我公田，遂及我私。彼有不获稚，</p><p class="poem-stanza">此有不敛穧，彼有遗秉，此有滞穗，伊寡妇之利。</p><p class="poem-stanza">曾孙来止，以其妇子。馌彼南亩，田畯至喜。来方禋祀，</p><p class="poem-stanza">以其骍黑，与其黍稷。以享以祀，以介景福。</p></div>',3)])])}const u=s(p,[["render",c]]);export{d as __pageData,u as default};
